#include <WiFi.h>
#include <WebServer.h>
#include "secrets.h"

const char* ssid = "PA";
const char* password = "148009pa@";

WebServer server(80);

#define RELAY_PIN 4

// Đổi thành LOW nếu relay của bạn kích mức LOW
#define RELAY_ON  HIGH
#define RELAY_OFF LOW

bool xeDangBat = false;

void trangChu() {
  String html = R"rawliteral(
<!DOCTYPE html>
<html>
<head>
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Dieu khien xe</title>
<style>
body {
  font-family: Arial;
  text-align: center;
  background: #111;
  color: white;
  padding-top: 60px;
}
button {
  width: 220px;
  height: 70px;
  margin: 15px;
  border: none;
  border-radius: 15px;
  font-size: 25px;
  font-weight: bold;
}
.on {
  background: #00c853;
  color: white;
}
.off {
  background: #d50000;
  color: white;
}
</style>
</head>

<body>

<h1>🚗 ĐIỀU KHIỂN XE</h1>

<button class="on" onclick="location.href='/bat'">
BẬT XE
</button>

<br>

<button class="off" onclick="location.href='/tat'">
TẮT XE
</button>

</body>
</html>
)rawliteral";

  server.send(200, "text/html", html);
}

void batXe() {
  digitalWrite(RELAY_PIN, RELAY_ON);
  xeDangBat = true;

  server.sendHeader("Location", "/");
  server.send(303);
}

void tatXe() {
  digitalWrite(RELAY_PIN, RELAY_OFF);
  xeDangBat = false;

  server.sendHeader("Location", "/");
  server.send(303);
}

void setup() {
  Serial.begin(115200);

  pinMode(RELAY_PIN, OUTPUT);
  digitalWrite(RELAY_PIN, RELAY_OFF);

  WiFi.softAP(ssid, password);

  Serial.println();
  Serial.println("WiFi da khoi dong");
  Serial.print("IP: ");
  Serial.println(WiFi.softAPIP());

  server.on("/", trangChu);
  server.on("/bat", batXe);
  server.on("/tat", tatXe);

  server.begin();

  Serial.println("Web server da khoi dong");
}

void loop() {
  server.handleClient();
}
